import HeroSectionV5 from "./hero-section-v5"

export default function Page() {
  return <HeroSectionV5 />
}

"use client"

import PromptInput from "./prompt-input"
import { usePlaceholderLoop } from "../hooks/use-placeholder-loop"
import "../styles/simple-chatbot.css"

export default function SimpleChatbot() {
  const { displayText, showCursor, caretSolid } = usePlaceholderLoop()

  return (
    <div className="scb-root scb-page">
      <div className="scb-page-inner">
        <PromptInput
          displayText={displayText}
          showCursor={showCursor}
          caretSolid={caretSolid}
        />
      </div>
    </div>
  )
}

import { useLayoutEffect, useReducer } from "react"

import {
  BETWEEN_MS,
  DELETE_CHAR_MS_FAST,
  DELETE_CHAR_MS_SLOW,
  HOLD_MS,
  PLACEHOLDER_PROMPTS,
  TYPE_CHAR_MS_FAST,
  TYPE_CHAR_MS_SLOW,
} from "../lib/config"

function typeDelayMs(charIdx: number, len: number): number {
  if (len <= 0) return TYPE_CHAR_MS_SLOW
  const t = charIdx / len
  const ease = Math.pow(1 - t, 0.28)
  return Math.round(
    TYPE_CHAR_MS_FAST + (TYPE_CHAR_MS_SLOW - TYPE_CHAR_MS_FAST) * ease
  )
}

function deleteDelayMs(charIdx: number, len: number): number {
  if (len <= 0) return DELETE_CHAR_MS_SLOW
  const t = charIdx / len
  const ease = Math.pow(t, 0.38)
  return Math.round(
    DELETE_CHAR_MS_FAST + (DELETE_CHAR_MS_SLOW - DELETE_CHAR_MS_FAST) * ease
  )
}

type Phase = "typingIn" | "hold" | "typingOut" | "between"

type State = {
  phase: Phase
  promptIdx: number
  charIdx: number
}

type Action =
  | { type: "ADVANCE_CHAR" }
  | { type: "SET_PHASE"; phase: Phase; charIdx?: number; promptIdx?: number }
  | { type: "REWIND_CHAR" }

const INITIAL: State = { phase: "typingIn", promptIdx: 0, charIdx: 0 }

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "ADVANCE_CHAR":
      return { ...state, charIdx: state.charIdx + 1 }
    case "REWIND_CHAR":
      return { ...state, charIdx: Math.max(0, state.charIdx - 1) }
    case "SET_PHASE":
      return {
        phase: action.phase,
        charIdx: action.charIdx ?? state.charIdx,
        promptIdx: action.promptIdx ?? state.promptIdx,
      }
    default:
      return state
  }
}

export function usePlaceholderLoop() {
  const [state, dispatch] = useReducer(reducer, INITIAL)
  const { phase, promptIdx, charIdx } = state

  const text = PLACEHOLDER_PROMPTS[promptIdx] ?? ""
  const len = text.length

  const displayText = text.slice(0, charIdx)
  const showCursor =
    phase === "typingIn" || phase === "typingOut" || phase === "between" || phase === "hold"

  const caretSolid = phase === "typingIn" || phase === "typingOut"

  useLayoutEffect(() => {
    let t: ReturnType<typeof setTimeout>

    switch (phase) {
      case "typingIn":
        if (charIdx < len) {
          t = setTimeout(() => dispatch({ type: "ADVANCE_CHAR" }), typeDelayMs(charIdx, len))
        } else {
          dispatch({ type: "SET_PHASE", phase: "hold" })
        }
        break

      case "hold":
        t = setTimeout(() => dispatch({ type: "SET_PHASE", phase: "typingOut" }), HOLD_MS)
        break

      case "typingOut":
        if (charIdx > 0) {
          t = setTimeout(
            () => dispatch({ type: "REWIND_CHAR" }),
            deleteDelayMs(charIdx, len)
          )
        } else {
          dispatch({ type: "SET_PHASE", phase: "between", charIdx: 0 })
        }
        break

      case "between":
        t = setTimeout(() => {
          const next = (promptIdx + 1) % PLACEHOLDER_PROMPTS.length
          dispatch({
            type: "SET_PHASE",
            phase: "typingIn",
            charIdx: 0,
            promptIdx: next,
          })
        }, BETWEEN_MS)
        break
    }

    return () => clearTimeout(t)
  }, [phase, charIdx, len, promptIdx])

  return { displayText, showCursor, caretSolid }
}

/* simple-chatbot — prompt card with typing placeholder (light / dark via .dark ancestor) */

/* ── Tokens — light ───────────────────────────────────────────────────────── */

.scb-root {
  --scb-card-bg: #fafafa;
  --scb-card-border: #e4e4e7;
  --scb-card-ring: rgba(0, 0, 0, 0.06);

  --scb-prompt: #18181b;

  --scb-icon: #71717a;
  --scb-icon-hover: #18181b;
  --scb-icon-hover-bg: rgba(0, 0, 0, 0.06);

  --scb-mic-bg: #18181b;
  --scb-mic-fg: #fafafa;
}

/* ── Tokens — dark ────────────────────────────────────────────────────────── */

.dark .scb-root {
  --scb-card-bg: #0a0a0a;
  --scb-card-border: #262626;
  --scb-card-ring: rgba(255, 255, 255, 0.03);

  --scb-prompt: #fafafa;

  --scb-icon: #a1a1aa;
  --scb-icon-hover: #e4e4e7;
  --scb-icon-hover-bg: rgba(255, 255, 255, 0.06);

  --scb-mic-bg: #ffffff;
  --scb-mic-fg: #0a0a0a;
}

/* ── Page ─────────────────────────────────────────────────────────────────── */

.scb-page {
  padding: 18px 14px;
  display: flex;
  justify-content: center;
  width: 100%;
}

.scb-page-inner {
  width: 100%;
  max-width: 720px;
}

/* ── Card ─────────────────────────────────────────────────────────────────── */

.scb-card {
  border-radius: 12px;
  border: 1px solid var(--scb-card-border);
  background: var(--scb-card-bg);
  overflow: hidden;
  box-shadow: 0 0 0 1px var(--scb-card-ring);
}

/* ── Input zone ───────────────────────────────────────────────────────────── */

.scb-body {
  min-height: 76px;
  padding: 14px 14px 8px;
}

.scb-input {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  font-size: 14px;
  line-height: 1.5;
  min-height: 40px;
}

/* Softer typed copy; cursor stays a sharp "|" */
.scb-text {
  color: var(--scb-prompt);
  user-select: none;
  filter: blur(0.22px);
}

/* Pipe cursor: no blur / glow — blink only while idle (hold / between) */
.scb-caret {
  display: inline-block;
  margin-left: 2px;
  font-weight: 500;
  font-size: 1.22em;
  line-height: 1;
  color: var(--scb-prompt);
  vertical-align: text-top;
  flex-shrink: 0;
  transform: translateY(0.06em);
  filter: none;
  animation: scb-caret-blink 0.92s step-start infinite;
}

.scb-caret--solid {
  animation: none;
  opacity: 1;
}

/* ── Toolbar (shadcn Button + block tokens) ───────────────────────────────── */

.scb-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 2px 10px 10px 12px;
}

.scb-toolbar-left,
.scb-toolbar-right {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.scb-toolbar-left {
  flex-wrap: wrap;
}

.scb-root .scb-btn-icon {
  color: var(--scb-icon);
  background-color: transparent;
}

.scb-root .scb-btn-icon:hover {
  color: var(--scb-icon-hover);
  background-color: var(--scb-icon-hover-bg);
}

.scb-root .scb-btn-mic {
  color: var(--scb-mic-fg);
  background-color: var(--scb-mic-bg);
}

.scb-root .scb-btn-mic:hover {
  opacity: 0.95;
  color: var(--scb-mic-fg);
  background-color: var(--scb-mic-bg);
}

.scb-mic-icon {
  color: var(--scb-mic-fg);
}

/* ── Keyframes ────────────────────────────────────────────────────────────── */

@keyframes scb-caret-blink {
  0%, 45% { opacity: 1; }
  55%, 100% { opacity: 0; }
}
